api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Base Container */
.promo-home-container {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  margin-bottom: 50px;
}

/* Hero Banner */
.promo-hero-banner {
  background: url('https://media.istockphoto.com/id/1658938869/vector/motion-design-studio-designers-animators-storytellers-creating-motion-graphic-content.jpg?s=170667a&w=0&k=20&c=wRxjQHBVwu0Mi3-w-GF2-VcaZZ4ReOIDgmxOdIsGk_Q=') center/contain no-repeat;
  padding: 140px 20px;
  border-radius: 16px;
  color: #000;
  text-align: center;
}

.promo-hero-banner h1 {
  font-size: 32px;
  margin-bottom: 10px;
}

.promo-hero-banner p {
  font-size: 18px;
}

/* Promo Action Card */
.promo-action-card {
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin: 1px auto 50px auto;
  padding: 30px;
  max-width: 800px;
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
  text-align: center;
  position: relative;
  z-index: 10;
}

.promo-action-card .card-content i {
  font-size: 40px;
  color: #0078d4;
  margin-bottom: 10px;
}

.promo-action-card .card-content h2 {
  margin: 10px 0;
  color: #004080;
}

.promo-action-card .card-content p {
  color: #555;
  margin-bottom: 20px;
}

.promo-action-card button {
  background-color: #0078d4;
  color: #fff;
  border: none;
  padding: 12px 25px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 16px;
  transition: background-color 0.3s ease;
}

.promo-action-card button:hover {
  background-color: #005fa3;
}

/* Process Tracker */
.promo-process-tracker {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-top: 40px;
  flex-wrap: wrap;
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
  padding: 30px;
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
}

.promo-process-tracker .step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.promo-process-tracker .step i {
  font-size: 28px;
  color: #0078d4;
  margin-bottom: 5px;
}

.promo-process-tracker .step p {
  font-size: 14px;
  color: #333;
}

/* Decorative Elements */
.tracker-line {
  width: 30px;
  height: 2px;
  background-color: #0078d4;
  margin: 0 10px;
}

.custom-arrow {
  font-size: 10px;
  color: #0078d4;
  transform: scaleX(1);
  display: inline-block;
}
